@startuml

class Customer {
  + id : string
}

class Account {
  + id : string
}

class WebUser {
  + login_name : string
  + state : UserState
}

class ShoppingCart {
  + id : string
}

class Order {
  + number : string
  + status : string
}

class Payment {
  + id : string
}

class LineItem {
  + quantity : int
  + price : double
}

class Product {
  + id : string
  + name : string
}

enum UserState {
  New
  Active
  TemporaryBlocked
  Banned
}

WebUser extends Customer

Customer "1" -- "1" Account
Account "1" *-- "0..*" Order
Account "1" *-- "0..1" ShoppingCart
Account "1" -- "0..*" Payment
Customer "0..1" -- "0..1" ShoppingCart
Order "1" -- "0..*" Payment
Order "1" -- "*" LineItem
ShoppingCart "1" -- "*" LineItem
LineItem "*" -- "1" Product

@enduml

